def _depends_chain(rel: str) -> list[dict]:
    out, seen = [], set()
    stack = list(N.DEPENDS_ON.get(rel, []))
    while stack:
        dep = stack.pop(0)
        drel = dep["relation"]
        if drel in seen:
            continue
        seen.add(drel)
        out.append(dep)
        stack.extend(N.DEPENDS_ON.get(drel, []))
    return out


