def _coverages_exact(inputs: dict, rel: str, rung: str, source_u: str, target_u: str | None = None) -> list[tuple[str, dict]]:
    """Selected partitions in ASCENDING COVERAGE ID order (contract section 4, selection order).

    The caller's `coverages` map is built by the evaluator input reconstruction from a Python SET
    of ids, so its insertion order is hash-seeded and differs between processes. Several folds
    downstream are FIRST-WINS over this list -- `_conservative_entry`'s carrier, and `run_suff`'s
    nativeCause scan through it -- so an unordered list makes the emitted `deficiency` /
    `nativeCause` depend on process identity rather than on the logical input. Sorting here is the
    minimal fix that gives every such fold a deterministic logical input, and ascending id is the
    order the contract publishes, so a normative-only consumer can reproduce it.
    """
    out = []
    for cid, cov in (inputs.get("coverages") or {}).items():
        key = cov.get("key") or {}
        if key.get("relation") != rel or key.get("resolution") != rung:
            continue
        if key.get("sourceUniverse") != source_u:
            continue
        if target_u is not None and key.get("targetUniverse") != target_u:
            continue
        out.append((cid, cov))
    return sorted(out, key=lambda pair: pair[0])


def _scopes_exact(inputs: dict, rel: str, rung: str, source_u: str) -> list[tuple[str, dict]]:
    """Selected scopes in ASCENDING SCOPE ID order, for the same reason as `_coverages_exact`."""
    out = []
    for sid, sc in (inputs.get("scopes") or {}).items():
        if sc.get("relation") != rel or sc.get("resolution") != rung:
            continue
        if sc.get("sourceUniverse") != source_u:
            continue
        out.append((sid, sc))
    return sorted(out, key=lambda pair: pair[0])

