    available, unavailable = [], []
    if not plan:
        return available, unavailable
    for cell in plan.get("cells") or []:
        if cell.get("capabilityId") != cap:
            continue
        fam = LANG_FAMILY.get(cell.get("languageMode"))
        for b in cell.get("programBindings") or []:
