            rec["_family"] = fam
            rec["_enumerator"] = (b.get("enumerator") or {}).get("closureId")
            rec["_workspaceRoot"] = cell.get("workspaceRoot")
            if rec.get("universe") is None:
                unavailable.append(rec)
                continue
            available.append(rec)
    return available, unavailable
